def tr(schluessel, **kwargs):
    text = TEXTE.get(SPRACHE["aktuell"], {}).get(schluessel)
    if text is None and SPRACHE["aktuell"] == "es":
        text = TEXTE["en"].get(schluessel)          # untranslated Spanish texts: English
    if text is None:
        text = TEXTE["de"].get(schluessel, schluessel)
    if kwargs:
        try:
            text = text.format(**kwargs)
        except Exception:
            pass
    return text


def datum_text(datum, sprache=None, kurz=False):
    """Date as text in the UI language: German 23.10.2026, Spanish 23/10/2026, otherwise
    ISO 2026-10-23; `kurz` = two-digit year (narrow fields)."""
    sprache = sprache or SPRACHE["aktuell"]
    if sprache == "de":
        return datum.strftime("%d.%m.%y" if kurz else "%d.%m.%Y")
    if sprache == "es":
        return datum.strftime("%d/%m/%y" if kurz else "%d/%m/%Y")
    return datum.strftime("%y-%m-%d" if kurz else "%Y-%m-%d")


def setze_sprache(code):
    if code in TEXTE:
        SPRACHE["aktuell"] = code
